const VIDEO_EXPORT_CONFIG = {
  bitrate: 100000000,
  bitrateMbps: 100,
  codec: "vp9",
  container: "mp4",
  resolution: "3840x2160",
  aspectRatio: "16:9",
  fps: 60,
  duration: 20
};

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const TAU = Math.PI * 2;
  const u = minSide * 0.001;

  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = "transparent";
  ctx.imageSmoothingEnabled = true;
  ctx.lineCap = "butt";
  ctx.lineJoin = "miter";

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function easeInOutSine(p) {
    return 0.5 - 0.5 * Math.cos(Math.PI * clamp(p, 0, 1));
  }

  function fillRoundRect(x, y, w, h, r, fillStyle, strokeStyle, lineWidth) {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
    if (fillStyle) {
      ctx.fillStyle = fillStyle;
      ctx.fill();
    }
    if (strokeStyle && lineWidth > 0) {
      ctx.strokeStyle = strokeStyle;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // =========================================================================
  // 1. CLEAN LAYERED SKY BACKGROUND (NO GLOW, FLAT VECTOR BANDS)
  // =========================================================================
  ctx.fillStyle = "#F0F6FA";
  ctx.fillRect(0, 0, width, height);

  ctx.fillStyle = "#E6F0F7";
  ctx.fillRect(0, height * 0.14, width, height * 0.18);

  ctx.fillStyle = "#DCEAF4";
  ctx.fillRect(0, height * 0.32, width, height * 0.23);

  // Subtle Distant Architectural Hills (Strictly in Background Band Y: 0.43 - 0.55)
  ctx.fillStyle = "#CBE4D5";
  ctx.beginPath();
  ctx.moveTo(0, height * 0.55);
  ctx.lineTo(0, height * 0.46);
  ctx.lineTo(width * 0.16, height * 0.43);
  ctx.lineTo(width * 0.34, height * 0.49);
  ctx.lineTo(width * 0.68, height * 0.49);
  ctx.lineTo(width * 0.84, height * 0.43);
  ctx.lineTo(width, height * 0.46);
  ctx.lineTo(width, height * 0.55);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = "#B5D8C4";
  ctx.beginPath();
  ctx.moveTo(0, height * 0.55);
  ctx.lineTo(0, height * 0.50);
  ctx.lineTo(width * 0.24, height * 0.47);
  ctx.lineTo(width * 0.36, height * 0.52);
  ctx.lineTo(width * 0.70, height * 0.52);
  ctx.lineTo(width * 0.88, height * 0.47);
  ctx.lineTo(width, height * 0.50);
  ctx.lineTo(width, height * 0.55);
  ctx.closePath();
  ctx.fill();

  // =========================================================================
  // 2. TOP TELEMETRY HUD BAR (BAND 1: Y 0.025 to 0.125)
  // =========================================================================
  const hudY = height * 0.025;
  const hudH = height * 0.098;
  const hudMarginX = width * 0.035;
  const hudGap = width * 0.018;
  const hudCardW = (width - hudMarginX * 2 - hudGap * 3) / 4;

  const fontTitle = `${Math.round(11 * u)}px "Segoe UI", Roboto, Helvetica, Arial, sans-serif`;
  const fontVal = `bold ${Math.round(20 * u)}px "Segoe UI", Roboto, Helvetica, Arial, sans-serif`;
  const fontSub = `bold ${Math.round(11 * u)}px "Segoe UI", Roboto, Helvetica, Arial, sans-serif`;

  for (let i = 0; i < 4; i++) {
    const cx = hudMarginX + i * (hudCardW + hudGap);
    fillRoundRect(cx, hudY, hudCardW, hudH, 8 * u, "#FFFFFF", "#C9DBE8", 1.8 * u);

    ctx.fillStyle = i % 2 === 0 ? "#10B981" : "#0284C7";
    ctx.fillRect(cx + 14 * u, hudY, hudCardW - 28 * u, 3.5 * u);

    if (i === 0) {
      ctx.fillStyle = "#475569";
      ctx.font = fontTitle;
      ctx.textAlign = "left";
      ctx.textBaseline = "top";
      ctx.fillText("RENEWABLE GRID OUTPUT", cx + 16 * u, hudY + 13 * u);

      const mwValue = (480 + 18 * Math.sin(sceneProgress * TAU)).toFixed(1);
      ctx.fillStyle = "#0F172A";
      ctx.font = fontVal;
      ctx.fillText(`${mwValue} MW`, cx + 16 * u, hudY + 31 * u);

      const barAreaX = cx + hudCardW * 0.56;
      const barAreaW = hudCardW * 0.36;
      const segCount = 8;
      const segGap = 3.5 * u;
      const segW = (barAreaW - segGap * (segCount - 1)) / segCount;
      const activeSegs = 6 + Math.round(1.5 + 0.5 * Math.sin(sceneProgress * TAU * 2));
      for (let s = 0; s < segCount; s++) {
        const sx = barAreaX + s * (segW + segGap);
        const sh = (16 + s * 2.2) * u;
        const sy = hudY + hudH - 16 * u - sh;
        ctx.fillStyle = s < activeSegs ? "#10B981" : "#E2E8F0";
        ctx.fillRect(sx, sy, segW, sh);
      }

      ctx.fillStyle = "#10B981";
      ctx.font = fontSub;
      ctx.fillText("100% CLEAN SYNC", cx + 16 * u, hudY + hudH - 22 * u);
    } else if (i === 1) {
      ctx.fillStyle = "#475569";
      ctx.font = fontTitle;
      ctx.textAlign = "left";
      ctx.textBaseline = "top";
      ctx.fillText("SOLAR ARRAY EFFICIENCY", cx + 16 * u, hudY + 13 * u);

      const effVal = (96.2 + 2.4 * Math.sin(sceneProgress * TAU + 1.2)).toFixed(1);
      ctx.fillStyle = "#0F172A";
      ctx.font = fontVal;
      ctx.fillText(`${effVal}%`, cx + 16 * u, hudY + 31 * u);

      const trackX = cx + 16 * u;
      const trackY = hudY + hudH - 20 * u;
      const trackW = hudCardW - 32 * u;
      const trackH = 8 * u;
      fillRoundRect(trackX, trackY, trackW, trackH, 4 * u, "#E2E8F0", null, 0);
      const fillRatio = 0.84 + 0.1 * Math.sin(sceneProgress * TAU + 1.2);
      fillRoundRect(trackX, trackY, trackW * fillRatio, trackH, 4 * u, "#F59E0B", null, 0);

      const sunIconX = cx + hudCardW - 28 * u;
      const sunIconY = hudY + 34 * u;
      ctx.beginPath();
      ctx.arc(sunIconX, sunIconY, 9 * u, 0, TAU);
      ctx.fillStyle = "#F59E0B";
      ctx.fill();
      ctx.strokeStyle = "#F59E0B";
      ctx.lineWidth = 2 * u;
      for (let r = 0; r < 8; r++) {
        const ang = (r / 8) * TAU + sceneProgress * TAU;
        ctx.beginPath();
        ctx.moveTo(sunIconX + Math.cos(ang) * 12 * u, sunIconY + Math.sin(ang) * 12 * u);
        ctx.lineTo(sunIconX + Math.cos(ang) * 16 * u, sunIconY + Math.sin(ang) * 16 * u);
        ctx.stroke();
      }
    } else if (i === 2) {
      ctx.fillStyle = "#475569";
      ctx.font = fontTitle;
      ctx.textAlign = "left";
      ctx.textBaseline = "top";
      ctx.fillText("WIND TURBINE TELEMETRY", cx + 16 * u, hudY + 13 * u);

      ctx.fillStyle = "#0F172A";
      ctx.font = fontVal;
      ctx.fillText("OPTIMAL", cx + 16 * u, hudY + 31 * u);

      ctx.fillStyle = "#0284C7";
      ctx.font = fontSub;
      ctx.fillText("5 UNITS ONLINE", cx + 16 * u, hudY + hudH - 22 * u);

      const waveX = cx + hudCardW * 0.50;
      const waveY = hudY + 30 * u;
      const waveW = hudCardW * 0.43;
      const waveH = hudH - 44 * u;
      fillRoundRect(waveX, waveY, waveW, waveH, 4 * u, "#F1F5F9", "#CBD5E1", 1.2 * u);

      ctx.save();
      ctx.beginPath();
      ctx.rect(waveX + 2 * u, waveY + 2 * u, waveW - 4 * u, waveH - 4 * u);
      ctx.clip();

      ctx.beginPath();
      const steps = 28;
      for (let s = 0; s <= steps; s++) {
        const px = waveX + 4 * u + ((waveW - 8 * u) * s) / steps;
        const phase = (s / steps) * TAU * 1.5 - sceneProgress * TAU * 3;
        const py = waveY + waveH * 0.5 + Math.sin(phase) * (waveH * 0.28);
        if (s === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.strokeStyle = "#0284C7";
      ctx.lineWidth = 2.4 * u;
      ctx.stroke();
      ctx.restore();
    } else if (i === 3) {
      ctx.fillStyle = "#475569";
      ctx.font = fontTitle;
      ctx.textAlign = "left";
      ctx.textBaseline = "top";
      ctx.fillText("GRID STORAGE & EV LOAD", cx + 16 * u, hudY + 13 * u);

      const capVal = Math.round(92 + 6 * Math.sin(sceneProgress * TAU));
      ctx.fillStyle = "#0F172A";
      ctx.font = fontVal;
      ctx.fillText(`${capVal}% FULL`, cx + 16 * u, hudY + 31 * u);

      ctx.fillStyle = "#10B981";
      ctx.font = fontSub;
      ctx.fillText("ZERO EMISSION", cx + 16 * u, hudY + hudH - 22 * u);

      const ringX = cx + hudCardW - 34 * u;
      const ringY = hudY + hudH * 0.54;
      const ringR = 20 * u;

      ctx.beginPath();
      ctx.arc(ringX, ringY, ringR, 0, TAU);
      ctx.strokeStyle = "#E2E8F0";
      ctx.lineWidth = 5 * u;
      ctx.stroke();

      const endAngle = -Math.PI * 0.5 + TAU * (capVal / 100);
      ctx.beginPath();
      ctx.arc(ringX, ringY, ringR, -Math.PI * 0.5, endAngle);
      ctx.strokeStyle = "#10B981";
      ctx.lineWidth = 5 * u;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(ringX, ringY, 6 * u, 0, TAU);
      ctx.fillStyle = "#0F172A";
      ctx.fill();
    }
  }

  // =========================================================================
  // 3. SKY LANE: GEOMETRIC SUN & NON-OVERLAPPING CLOUDS (BAND 2: Y 0.145 - 0.24)
  // =========================================================================
  const sunX = width * 0.085;
  const sunY = height * 0.195;
  const sunCoreR = 22 * u;

  ctx.beginPath();
  ctx.arc(sunX, sunY, sunCoreR + 13 * u, 0, TAU);
  ctx.fillStyle = "#FEF3C7";
  ctx.fill();
  ctx.strokeStyle = "#F59E0B";
  ctx.lineWidth = 1.6 * u;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(sunX, sunY, sunCoreR, 0, TAU);
  ctx.fillStyle = "#F59E0B";
  ctx.fill();

  const sunTicks = 12;
  for (let i = 0; i < sunTicks; i++) {
    const ang = (i / sunTicks) * TAU + sceneProgress * TAU;
    const r1 = sunCoreR + 4 * u;
    const r2 = sunCoreR + 9 * u;
    ctx.beginPath();
    ctx.moveTo(sunX + Math.cos(ang) * r1, sunY + Math.sin(ang) * r1);
    ctx.lineTo(sunX + Math.cos(ang) * r2, sunY + Math.sin(ang) * r2);
    ctx.strokeStyle = "#D97706";
    ctx.lineWidth = 2.2 * u;
    ctx.stroke();
  }

  function drawFlatCloud(cx, cy, scale) {
    if (scale <= 0.01) return;
    const w = 84 * u * scale;
    const h = 24 * u * scale;
    fillRoundRect(cx - w * 0.5, cy - h * 0.5, w, h, h * 0.5, "#FFFFFF", "#CBDCE8", 1.5 * u);
    ctx.beginPath();
    ctx.arc(cx - w * 0.16, cy - h * 0.35, 13 * u * scale, Math.PI, TAU);
    ctx.arc(cx + w * 0.12, cy - h * 0.45, 16 * u * scale, Math.PI, TAU);
    ctx.closePath();
    ctx.fillStyle = "#FFFFFF";
    ctx.fill();
  }

  const cloudCount = 4;
  const cloudStartX = width * 0.18;
  const cloudEndX = width * 0.94;
  const cloudTrackW = cloudEndX - cloudStartX;

  for (let c = 0; c < cloudCount; c++) {
    const rawP = (c / cloudCount + sceneProgress) % 1;
    const cx = cloudStartX + rawP * cloudTrackW;
    const cy = height * (c % 2 === 0 ? 0.175 : 0.212);
    let edgeScale = 1;
    if (rawP < 0.08) edgeScale = easeInOutSine(rawP / 0.08);
    else if (rawP > 0.92) edgeScale = easeInOutSine((1 - rawP) / 0.08);
    drawFlatCloud(cx, cy, edgeScale * (c % 2 === 0 ? 1.0 : 0.85));
  }

  // =========================================================================
  // 4. SKYLINE & WIND TURBINES BAND (BAND 3: Y 0.25 to 0.55)
  // =========================================================================
  const horizonY = height * 0.55;

  function drawWindTurbine(baseX, baseY, hubY, bladeLen, phaseOffset) {
    const towerTopW = 5.5 * u;
    const towerBotW = 13 * u;

    fillRoundRect(baseX - 18 * u, baseY - 6 * u, 36 * u, 6 * u, 2 * u, "#64748B", null, 0);

    ctx.beginPath();
    ctx.moveTo(baseX - towerTopW * 0.5, hubY);
    ctx.lineTo(baseX + towerTopW * 0.5, hubY);
    ctx.lineTo(baseX + towerBotW * 0.5, baseY - 6 * u);
    ctx.lineTo(baseX - towerBotW * 0.5, baseY - 6 * u);
    ctx.closePath();
    ctx.fillStyle = "#FFFFFF";
    ctx.fill();
    ctx.strokeStyle = "#94A3B8";
    ctx.lineWidth = 1.6 * u;
    ctx.stroke();

    ctx.fillStyle = "#10B981";
    ctx.fillRect(baseX - towerBotW * 0.38, baseY - 26 * u, towerBotW * 0.76, 5 * u);

    fillRoundRect(baseX - 9 * u, hubY - 6 * u, 18 * u, 12 * u, 4 * u, "#E2E8F0", "#64748B", 1.5 * u);

    const rotAngle = sceneProgress * TAU * 2 + phaseOffset;
    for (let b = 0; b < 3; b++) {
      const ang = rotAngle + (b * TAU) / 3;
      ctx.save();
      ctx.translate(baseX, hubY);
      ctx.rotate(ang);

      ctx.beginPath();
      ctx.moveTo(0, -2.2 * u);
      ctx.lineTo(bladeLen * 0.22, -5.2 * u);
      ctx.lineTo(bladeLen, -1.4 * u);
      ctx.lineTo(bladeLen, 1.4 * u);
      ctx.lineTo(bladeLen * 0.22, 3.2 * u);
      ctx.lineTo(0, 2.2 * u);
      ctx.closePath();
      ctx.fillStyle = "#FFFFFF";
      ctx.fill();
      ctx.strokeStyle = "#64748B";
      ctx.lineWidth = 1.4 * u;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(bladeLen * 0.82, -1.8 * u);
      ctx.lineTo(bladeLen, -1.4 * u);
      ctx.lineTo(bladeLen, 1.4 * u);
      ctx.lineTo(bladeLen * 0.82, 1.6 * u);
      ctx.closePath();
      ctx.fillStyle = "#10B981";
      ctx.fill();

      ctx.restore();
    }

    ctx.beginPath();
    ctx.arc(baseX, hubY, 5.5 * u, 0, TAU);
    ctx.fillStyle = "#0F172A";
    ctx.fill();
    ctx.beginPath();
    ctx.arc(baseX, hubY, 2.5 * u, 0, TAU);
    ctx.fillStyle = "#10B981";
    ctx.fill();
  }

  const bladeL = 56 * u;
  const hubLevel = height * 0.355;
  drawWindTurbine(width * 0.085, horizonY, hubLevel, bladeL, 0.0);
  drawWindTurbine(width * 0.185, horizonY, hubLevel, bladeL, 0.7);
  drawWindTurbine(width * 0.285, horizonY, hubLevel, bladeL, 1.4);

  drawWindTurbine(width * 0.79, horizonY, hubLevel, bladeL, 0.35);
  drawWindTurbine(width * 0.89, horizonY, hubLevel, bladeL, 1.05);

  // =========================================================================
  // CENTER SMART ECO-CITY BUILDINGS (PERFECT SYMMETRIC ARCHITECTURAL GRID)
  // =========================================================================
  const buildings = [
    { x: width * 0.370, w: width * 0.068, h: height * 0.230, cols: 4, rows: 7, accent: "#10B981", roofType: "solar" },
    { x: width * 0.452, w: width * 0.082, h: height * 0.275, cols: 5, rows: 9, accent: "#0284C7", roofType: "spire" },
    { x: width * 0.548, w: width * 0.068, h: height * 0.215, cols: 4, rows: 6, accent: "#10B981", roofType: "solar" },
    { x: width * 0.630, w: width * 0.072, h: height * 0.245, cols: 4, rows: 8, accent: "#0EA5E9", roofType: "terrace" }
  ];

  buildings.forEach((b, bIdx) => {
    const bx = Math.round(b.x);
    const bw = Math.round(b.w);
    const bh = Math.round(b.h);
    const by = Math.round(horizonY - bh);

    // 1. Symmetrical Level Rooftop Architectural Elements (No slanted overlap)
    if (b.roofType === "solar") {
      const rackW = Math.round(bw * 0.78);
      const rackX = bx + Math.round((bw - rackW) * 0.5);
      const postH = Math.round(8 * u);
      const panelH = Math.round(6 * u);

      // Symmetrical vertical support struts
      ctx.fillStyle = "#475569";
      ctx.fillRect(rackX + Math.round(rackW * 0.18), by - postH, Math.max(2, Math.round(3 * u)), postH);
      ctx.fillRect(rackX + Math.round(rackW * 0.50 - 1.5 * u), by - postH, Math.max(2, Math.round(3 * u)), postH);
      ctx.fillRect(rackX + Math.round(rackW * 0.82 - 3 * u), by - postH, Math.max(2, Math.round(3 * u)), postH);

      // Horizontal Solar Canopy Deck
      fillRoundRect(rackX, by - postH - panelH, rackW, panelH, 2 * u, "#0284C7", "#0F172A", 1.5 * u);

      // Solar Deck Cell Dividers
      ctx.fillStyle = "#BAE6FD";
      for (let s = 1; s < 4; s++) {
        ctx.fillRect(rackX + Math.round((rackW * s) / 4), by - postH - panelH + Math.round(1.5 * u), Math.max(1, Math.round(1.2 * u)), panelH - Math.round(3 * u));
      }
    } else if (b.roofType === "spire") {
      const tier1W = Math.round(bw * 0.72);
      const tier1H = Math.round(10 * u);
      const tier1X = bx + Math.round((bw - tier1W) * 0.5);

      const tier2W = Math.round(bw * 0.44);
      const tier2H = Math.round(9 * u);
      const tier2X = bx + Math.round((bw - tier2W) * 0.5);

      fillRoundRect(tier1X, by - tier1H, tier1W, tier1H, 2 * u, "#1E293B", "#0F172A", 1.5 * u);
      fillRoundRect(tier2X, by - tier1H - tier2H, tier2W, tier2H, 2 * u, "#10B981", "#0F172A", 1.5 * u);
    } else if (b.roofType === "terrace") {
      const crownW = Math.round(bw * 0.80);
      const crownH = Math.round(10 * u);
      const crownX = bx + Math.round((bw - crownW) * 0.5);
      fillRoundRect(crownX, by - crownH, crownW, crownH, 3 * u, "#10B981", "#059669", 1.5 * u);
    }

    // 2. Main Building Outer Structure (Uniform solid facade, no asymmetric half-strip behind windows)
    fillRoundRect(bx, by, bw, bh, 3 * u, "#1E293B", "#0F172A", 2 * u);

    // 3. Top Roof Parapet Cap & Accent Fascia Bar
    const parapetH = Math.round(5 * u);
    ctx.fillStyle = "#0F172A";
    ctx.fillRect(bx, by, bw, parapetH);

    const fasciaY = by + parapetH + Math.round(2 * u);
    const fasciaH = Math.round(4.5 * u);
    ctx.fillStyle = b.accent;
    ctx.fillRect(bx + Math.round(2 * u), fasciaY, bw - Math.round(4 * u), fasciaH);

    // 4. Symmetrical Vertical Side Pilasters & Eco-Strips (Left & Right identical)
    const pilasterPad = Math.round(4.5 * u);
    const pilasterW = Math.round(3.5 * u);
    const pilasterTop = fasciaY + fasciaH + Math.round(6 * u);
    const lobbyH = Math.round(15 * u);
    const pilasterBot = Math.round(horizonY) - lobbyH - Math.round(5 * u);
    const pilasterH = Math.max(10, pilasterBot - pilasterTop);

    ctx.fillStyle = b.accent;
    ctx.fillRect(bx + pilasterPad, pilasterTop, pilasterW, pilasterH);
    ctx.fillRect(bx + bw - pilasterPad - pilasterW, pilasterTop, pilasterW, pilasterH);

    // 5. Recessed Architectural Window Bay (Provides a clean, uniform frame around the window grid)
    const bayPadX = pilasterPad + pilasterW + Math.round(5 * u);
    const bayX = bx + bayPadX;
    const bayW = bw - bayPadX * 2;
    const bayY = pilasterTop;
    const bayH = pilasterH;

    fillRoundRect(bayX, bayY, bayW, bayH, 2 * u, "#0F172A", "#334155", 1.2 * u);

    // 6. Pixel-Snapped Precision Window Grid inside the Recessed Bay
    const gridInnerPadX = Math.round(4.5 * u);
    const gridInnerPadY = Math.round(4.5 * u);
    const gridAvailW = bayW - gridInnerPadX * 2;
    const gridAvailH = bayH - gridInnerPadY * 2;

    const colGap = Math.max(2, Math.round(4 * u));
    const rowGap = Math.max(2, Math.round(4.5 * u));

    const winW = Math.floor((gridAvailW - colGap * (b.cols - 1)) / b.cols);
    const winH = Math.floor((gridAvailH - rowGap * (b.rows - 1)) / b.rows);

    // Center the exact integer grid inside the bay so left/right & top/bottom margins are 100% equal
    const totalGridW = winW * b.cols + colGap * (b.cols - 1);
    const totalGridH = winH * b.rows + rowGap * (b.rows - 1);
    const startWinX = bayX + Math.round((bayW - totalGridW) * 0.5);
    const startWinY = bayY + Math.round((bayH - totalGridH) * 0.5);

    for (let r = 0; r < b.rows; r++) {
      const wy = startWinY + r * (winH + rowGap);
      for (let c = 0; c < b.cols; c++) {
        const wx = startWinX + c * (winW + colGap);

        // Smooth, deterministic energy-saving window wave across floors
        const waveVal = Math.sin(sceneProgress * TAU * 2 - r * 0.45 + c * 0.35 + bIdx * 0.8);
        let paneColor = "#1E293B";
        let headerColor = "#334155";

        if (waveVal > 0.28) {
          if ((r + c + bIdx) % 3 === 0) {
            paneColor = "#34D399";
            headerColor = "#A7F3D0";
          } else {
            paneColor = "#38BDF8";
            headerColor = "#BAE6FD";
          }
        } else if (waveVal > -0.18) {
          paneColor = "#334155";
          headerColor = "#475569";
        }

        // Window Pane Base
        ctx.fillStyle = paneColor;
        ctx.fillRect(wx, wy, winW, winH);

        // Crisp Top Transom Highlight Bar inside each window cell for architectural depth
        const transomH = Math.max(1, Math.round(winH * 0.22));
        ctx.fillStyle = headerColor;
        ctx.fillRect(wx, wy, winW, transomH);
      }
    }

